import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    edges = []
    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        edges.append((u, v, w, i))

    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        for node in path:
            parent[node] = x
        return x

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_x] = root_y
            return True
        return False

    mst_edges = set()
    parent = list(range(n + 1))
    edges_in_mst = 0

    for u, v, w, idx in sorted_edges:
        if union(u, v):
            mst_edges.add(idx)
            edges_in_mst += 1
            if edges_in_mst == n - 1:
                break

    ans = [0] * m

    for u, v, w, idx in edges:
        if idx in mst_edges:
            ans[idx] = w
        else:
            max_w = -1
            temp_parent = list(range(n + 1))

            def find_temp(x):
                path = []
                while temp_parent[x] != x:
                    path.append(x)
                    x = temp_parent[x]
                for node in path:
                    temp_parent[node] = x
                return x

            def union_temp(x, y):
                root_x = find_temp(x)
                root_y = find_temp(y)
                if root_x != root_y:
                    temp_parent[root_x] = root_y
                    return True
                return False

            for eu, ev, ew, eidx in sorted_edges:
                if eidx == idx:
                    continue
                if eidx in mst_edges:
                    union_temp(eu, ev)

            root_u = find_temp(u)
            root_v = find_temp(v)

            if root_u != root_v:
                ans[idx] = w
            else:
                for eu, ev, ew, eidx in sorted_edges:
                    if eidx == idx:
                        continue
                    if eidx in mst_edges:
                        continue
                    if find_temp(eu) != find_temp(ev):
                        if ew > max_w:
                            max_w = ew
                        union_temp(eu, ev)
                ans[idx] = max_w if max_w != -1 else w

    output_lines = [str(ans[i]) for i in range(m)]
    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == "__main__":
    main()
